package br.com.luvi.financaspessoais.transferencia.service;import br.com.luvi.financaspessoais.conta.repository.ContaFinanceiraRepository;import br.com.luvi.financaspessoais.conta.service.ContaService;import br.com.luvi.financaspessoais.transferencia.dto.*;import br.com.luvi.financaspessoais.transferencia.entity.*;import br.com.luvi.financaspessoais.transferencia.repository.*;import br.com.luvi.financaspessoais.usuario.entity.Usuario;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.time.*;import java.util.*;@Service public class TransferenciaService{private final TransferenciaRepository repo;private final ContaFinanceiraRepository contas;private final ContaService contaService;public TransferenciaService(TransferenciaRepository r,ContaFinanceiraRepository c,ContaService s){repo=r;contas=c;contaService=s;}@Transactional public TransferenciaResponse criar(TransferenciaRequest r,Usuario u){if(r.origemId().equals(r.destinoId()))throw new IllegalArgumentException("Origem e destino devem ser diferentes.");if(!contaService.podeAcessar(r.origemId(),u)||!contaService.podeAcessar(r.destinoId(),u))throw new SecurityException("Conta não permitida.");Transferencia t=new Transferencia();t.setOrigem(contas.findById(r.origemId()).orElseThrow());t.setDestino(contas.findById(r.destinoId()).orElseThrow());t.setValor(r.valor());t.setData(r.data());t.setDescricao(r.descricao()==null||r.descricao().isBlank()?"Transferência":r.descricao().trim());t.setUsuarioCriacao(u);return TransferenciaResponse.from(repo.save(t));}@Transactional(readOnly=true)public List<TransferenciaResponse> listar(Collection<Long>ids,LocalDate i,LocalDate f){if(ids.isEmpty())return List.of();return repo.listar(ids,i,f).stream().map(TransferenciaResponse::from).toList();}@Transactional public void excluir(Long id,Usuario u){var t=repo.findById(id).orElseThrow();if(!contaService.podeAcessar(t.getOrigem().getId(),u)||!contaService.podeAcessar(t.getDestino().getId(),u))throw new SecurityException("Acesso negado.");repo.delete(t);}public BigDecimal saldoAntes(Collection<Long>ids,LocalDate d){return ids.isEmpty()?BigDecimal.ZERO:repo.saldoAntes(ids,d);}public BigDecimal saldoPeriodo(Collection<Long>ids,LocalDate i,LocalDate f){return ids.isEmpty()?BigDecimal.ZERO:repo.saldoPeriodo(ids,i,f);}public BigDecimal entradas(Long id,LocalDate i,LocalDate f){return repo.entradas(id,i,f);}public BigDecimal saidas(Long id,LocalDate i,LocalDate f){return repo.saidas(id,i,f);}}
